from typing import Dict, List, Optional

import fastjson

from edge.clock import day_of, parse_day


def upload(readings: List[Dict], since: Optional[str] = None) -> Dict:
    """Encode readings for the uplink, reporting what was sent and skipped."""
    since = parse_day(since)
    kept = []
    skipped = 0
    for reading in readings:
        if since is not None and day_of(reading["ts"]) < since:
            continue
        if reading["temp"] is None:
            skipped += 1
            continue
        kept.append(reading)
    payload = fastjson.dumps({"readings": [[r["ts"], r["sensor"], r["temp"]] for r in kept]})
    return {"sent": len(kept), "payload": payload, "skipped": skipped}
"}

